import logging
from taf.collectors.core import Collector
from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core.entities.executor import ExecutionError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AaShellLogCollector(Using("tool_executor"), Using("file_getter"), Collector):
    """
        Collector using the AaShell "log" command.
    """

    def __init__(self,
                 tool,
                 options=None,
                 target_file_name=None,
                 timeout=60,
                 **kwargs):
        super(AaShellLogCollector, self).__init__(**kwargs)
        self._tool = tool
        self._options = '-a' if options is None else options
        self._target_file_name = "aashell_{name}.zip".format(name=self._name) if target_file_name is None\
            else target_file_name
        self._timeout = timeout
        self.add_prerequisite(self._tool)

    def _collect(self, target_dir):
        log_command = "log {options} -z {target_file_name}".format(
            options=self._options,
            target_file_name=self._target_file_name)
        self._tool.execute(log_command.encode('utf-8'), timeout=self._timeout)
        source_path = self._get_source_file_path()
        self._file_getter.get_file(
            source_path=source_path,
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir, target_file_name=self._target_file_name))

    def _get_source_file_path(self):
        source_path_search_command = "find /tmp/ -name '{target_file_name}' 2>/dev/null".format(
            target_file_name=self._target_file_name)
        stdout, stderr, exit_status = self._tool_executor.raw_execute(source_path_search_command.encode('utf-8'))
        if stdout:
            return stdout.decode('utf-8').strip()
        else:
            raise ExecutionError(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status)

    def _file_cleanup_in_gnb(self):
        try:
            source_path = "'{source_path}'".format(
                source_path=self._get_source_file_path())
            file_cleanup_command = "rm -f {source_path}".format(source_path=source_path)
            self._tool_executor.execute(file_cleanup_command.encode('utf-8'))
        except ExecutionError:
            logger.debug("No zip file available in /tmp with name %r", self._target_file_name)

    def _setup(self):
        self._file_cleanup_in_gnb()

    def _teardown(self):
        self._file_cleanup_in_gnb()
